  display: flex;
  gap: 0.25rem;
  background: #f1f5f9;
  border-radius: 0.5rem;
  padding: 0.25rem;
}
.tab-btn {
  flex: 1;
  padding: 0.65rem 0.25rem;
  background: none;
  border: none;
